/** `slugify`, reserved slugs and `uniqueSlug` suffixing. */
import { describe, expect, it } from "vitest";
import {
  InvalidSlugError,
  RESERVED_SLUGS,
  SLUG_MAX_LENGTH,
  assertValidSlug,
  isReservedSlug,
  isValidSlug,
  projectKeyFromName,
  slugify,
  uniqueSlug,
} from "@/lib/slug";

describe("lib/slug", () => {
  it("lowercases and hyphenates a display name", () => {
    expect(slugify("Website Relaunch")).toBe("website-relaunch");
    expect(slugify("  Acme   Corp  ")).toBe("acme-corp");
  });

  it("strips diacritics and punctuation", () => {
    expect(slugify("Café Münster")).toBe("cafe-munster");
    expect(slugify("Q3 — Roadmap!")).toBe("q3-roadmap");
  });

  it("collapses runs of separators and trims leading/trailing hyphens", () => {
    expect(slugify("--hello___world--")).toBe("hello-world");
  });

  it("truncates to the maximum length without a trailing hyphen", () => {
    const slug = slugify("a".repeat(80));
    expect(slug.length).toBe(SLUG_MAX_LENGTH);
    expect(slug.endsWith("-")).toBe(false);
  });

  it("returns an empty string when there is nothing sluggable", () => {
    expect(slugify("!!!")).toBe("");
  });

  it("validates length and shape", () => {
    expect(isValidSlug("acme")).toBe(true);
    expect(isValidSlug("a")).toBe(false);
    expect(isValidSlug("Acme")).toBe(false);
    expect(isValidSlug("acme--corp")).toBe(false);
    expect(isValidSlug("-acme")).toBe(false);
    expect(isValidSlug("a".repeat(SLUG_MAX_LENGTH + 1))).toBe(false);
  });

  it("knows the router's reserved slugs", () => {
    expect(isReservedSlug("settings")).toBe(true);
    expect(isReservedSlug("acme")).toBe(false);
    for (const reserved of RESERVED_SLUGS) {
      expect(isReservedSlug(reserved), reserved).toBe(true);
    }
  });

  it("throws InvalidSlugError for malformed and reserved slugs", () => {
    expect(() => assertValidSlug("acme")).not.toThrow();
    expect(() => assertValidSlug("Acme!")).toThrow(InvalidSlugError);
    expect(() => assertValidSlug("billing")).toThrow(/reserved/);
  });

  it("returns the base slug when nothing has claimed it", () => {
    expect(uniqueSlug("Website Relaunch", [])).toBe("website-relaunch");
  });

  it("suffixes numerically until it finds a free slug", () => {
    expect(uniqueSlug("Acme", ["acme"])).toBe("acme-2");
    expect(uniqueSlug("Acme", ["acme", "acme-2", "acme-3"])).toBe("acme-4");
  });

  it("never returns a reserved slug, even as the base", () => {
    const slug = uniqueSlug("Settings", []);
    expect(slug).not.toBe("settings");
    expect(isReservedSlug(slug)).toBe(false);
  });

  it("falls back to `item` for input with no sluggable characters", () => {
    expect(uniqueSlug("???", [])).toBe("item");
  });
    expect(shape.fieldErrors?.slug?.[0]).toContain("is reserved");
  });

  it("maps a ZodError to field errors keyed by dotted path", () => {
    const parsed = schema.safeParse({ title: "no", estimate: 1.5 });
    expect(parsed.success).toBe(false);
    if (parsed.success) return;

    const fields = fieldErrorsFromZod(parsed.error);
    expect(Object.keys(fields).sort()).toEqual(["estimate", "title"]);
    expect(toAppError(parsed.error).code).toBe("validation_failed");
  });

  it("falls back to `internal_error` for an unknown throw", () => {
    expect(toAppError(new Error("boom")).code).toBe("internal_error");
    expect(toAppError("boom").code).toBe("internal_error");
    expect(toAppError("boom").message).toContain("Something went wrong");
  });

  it("recognises exactly the domain error classes", () => {
    expect(isDomainError(permissionError())).toBe(true);
    expect(isDomainError(new TenantScopeError(ORG_A, ORG_B))).toBe(true);
    expect(isDomainError(new InvalidSlugError("x", "too short"))).toBe(true);
    expect(isDomainError(new Error("boom"))).toBe(false);
    expect(isDomainError(null)).toBe(false);
  });

  it("gives every error code an HTTP status", () => {
    for (const [code, status] of Object.entries(HTTP_STATUS_BY_CODE)) {
      expect(status, code).toBeGreaterThanOrEqual(400);
    }
    expect(HTTP_STATUS_BY_CODE.rate_limited).toBe(429);
    expect(HTTP_STATUS_BY_CODE.plan_limit_exceeded).toBe(402);
  });

  it("wraps a failure as an ActionResult, never throwing", () => {
    const result = toActionResult(new AlreadyArchivedError("Project", "01PRJ"));
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.error.code).toBe("conflict");
    expect(typeof result.submittedAt).toBe("string");
  });

  it("keeps a cross-tenant org id out of the user-facing message", () => {
    const other = "01HZZZDDDDDDDDDDDDDDDDDDDD" as OrgId;
    expect(toAppError(new TenantScopeError(ORG_A, other)).message).toBe(
      "That resource belongs to a different organization.",
    );
  });
});

