/**
 * Sign-up, sign-in and password-reset rules from ADR 0003.
 *
 * Uses the real rate limiter (reset between tests) so the throttle is
 * exercised through the bucket tables rather than a canned verdict.
 */
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/hash", async () => (await import("../server/_support/doubles/misc")).hashModule);

import { requestPasswordResetAction } from "@/actions/auth/reset-password";
import {
  EmailAlreadyRegisteredError,
  RateLimitedError,
  isDomainError,
  toAppError,
} from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { consumeRateLimit, getBucketConfig, resetRateLimits } from "@/lib/rate-limit";
import { isReservedSlug, isValidSlug } from "@/lib/slug";
import { registerSchema } from "@/schemas/auth";
import { updateOrganizationSchema } from "@/schemas/organization";
import { getDb, organizations, users } from "@/server/db";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { login, register, confirmPasswordReset } from "@/server/services/auth-service";
import { useTemporaryDatabase } from "../server/_support/fixtures";
import type { RegisterInput } from "@/schemas/auth";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";

const PASSWORD = "Correct1Horse2";
const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

let cleanup: () => void;
let sequence = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

beforeEach(() => {
  resetRateLimits();
});

/** A parsed registration for a fresh address, the way the action hands it over. */
function signUp(overrides: Partial<RegisterInput> = {}): RegisterInput {
  sequence += 1;
  return registerSchema.parse({
    name: "Alice Alvarez",
    email: `person${sequence}@signup.test`,
    password: PASSWORD,
    confirmPassword: PASSWORD,
    acceptTerms: true,
    ...overrides,
  });
}

function countRows(table: typeof users | typeof organizations): number {
  return getDb().select().from(table).all().length;
}

describe("services/auth-service register", () => {
  it.each([
    ["Admin", "admin-2"],
    ["Billing", "billing-2"],
    ["Support", "support-2"],
    ["Taskflow", "taskflow-2"],
    ["Al", "al"],
  ])("signs up %s with the derived slug %s", async (name, slug) => {
    const { org } = await register(signUp({ name }));
    expect(org.slug).toBe(slug.replace(/-2$/, (m) => (isReservedSlug(slug.slice(0, -2)) ? m : "")) );
    expect(isValidSlug(org.slug)).toBe(true);
    expect(isReservedSlug(org.slug)).toBe(false);
  });

  it.each([["J"], ["山田"], ["!!!"]])(
    "falls back to `workspace` when %s leaves no usable slug",
    async (name) => {
      const first = await register(signUp({ name }));
      expect(first.org.slug).toMatch(/^workspace(-\d+)?$/);
      expect(first.org.name).toBe(`${name}'s workspace`);
    },
  );

  it("suffixes the fallback and derived slugs when they are taken", async () => {
    const one = await register(signUp({ name: "山田" }));
    const two = await register(signUp({ name: "田中" }));
    const three = await register(signUp({ name: "Casey" }));
    const four = await register(signUp({ name: "Casey" }));

    expect(one.org.slug).not.toBe(two.org.slug);
    expect(two.org.slug.startsWith("workspace-")).toBe(true);
    expect(three.org.slug).toBe("casey");
    expect(four.org.slug).toBe("casey-2");
  });

  it("shortens a long display name so the workspace name still fits", async () => {
    const name = `${"Bartholomew ".repeat(6)}Wolfeschlegelstein`.slice(0, 80);
    expect(name).toHaveLength(80);

    const { org } = await register(signUp({ name }));

    expect(org.name.length).toBeLessThanOrEqual(64);
    expect(org.name.endsWith("'s workspace")).toBe(true);
    expect(org.name.startsWith("Bartholomew")).toBe(true);
    expect(
      updateOrganizationSchema.safeParse({ orgId: org.id, name: org.name }).success,
    ).toBe(true);
  });

  it("does not split a surrogate pair when it shortens the name", async () => {
    const { org } = await register(signUp({ name: "😀".repeat(40) }));

    expect(org.name.length).toBeLessThanOrEqual(64);
    expect(org.name.endsWith("'s workspace")).toBe(true);
    expect(org.name).not.toMatch(/[\ud800-\udbff](?![\udc00-\udfff])/);
  });

  it("leaves a name that fits untouched", async () => {
    const { org } = await register(signUp({ name: "Dana" }));
    expect(org.name).toBe("Dana's workspace");
  });

  it("stores the address lowercased and treats spellings as one account", async () => {
    const { user } = await register(signUp({ email: "Mixed.Case@Signup.test" }));
    expect(user.email).toBe("mixed.case@signup.test");

    await expect(userRepo.findUserByEmail("MIXED.case@SIGNUP.test")).resolves.toMatchObject({
      id: user.id,
    });

    const before = { users: countRows(users), orgs: countRows(organizations) };
    await expect(
      register(signUp({ email: "mixed.case@signup.test" })),
    ).rejects.toBeInstanceOf(EmailAlreadyRegisteredError);
    expect({ users: countRows(users), orgs: countRows(organizations) }).toEqual(before);
  });

  it("finds an account stored before addresses were normalised", async () => {
    const stamp = new Date().toISOString();
    getDb()
      .insert(users)
      .values({
        id: "01HZZZZZZZZZZZZZZZZZZZZZZZ",
        email: "Legacy@Signup.test",
        name: "Legacy",
        passwordHash: "seed",
        timezone: "UTC",
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    await expect(userRepo.findUserByEmail("legacy@signup.test")).resolves.toMatchObject({
      name: "Legacy",
    });
    await expect(register(signUp({ email: "legacy@signup.test" }))).rejects.toBeInstanceOf(
      EmailAlreadyRegisteredError,
    );
  });

  it("refuses an existing address as a conflict and creates nothing", async () => {
    const input = signUp();
    await register(input);

    const before = { users: countRows(users), orgs: countRows(organizations) };
    const refused = await register(signUp({ email: input.email })).catch((e: unknown) => e);

    expect(refused).toBeInstanceOf(EmailAlreadyRegisteredError);
    expect(isDomainError(refused)).toBe(true);
    expect(toAppError(refused).code).toBe("conflict");
    expect({ users: countRows(users), orgs: countRows(organizations) }).toEqual(before);
  });

  it("turns a lost race on the unique index into the same conflict", async () => {
    const email = "racer@signup.test";
    const results = await Promise.allSettled([
      register(signUp({ email })),
      register(signUp({ email })),
    ]);

    expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(1);
    const rejected = results.find((r) => r.status === "rejected");
    expect(rejected?.status === "rejected" && rejected.reason).toBeInstanceOf(
      EmailAlreadyRegisteredError,
    );
  });

  it("starts the workspace on the free plan with an active subscription", async () => {
    const { org } = await register(signUp());
    const subscription = await subscriptionRepo.findSubscription(org.id);

    expect(org.plan).toBe("free");
    expect(subscription).toMatchObject({ plan: "free", status: "active" });
  });

  it("publishes member.joined for the owner exactly once", async () => {
    const joined: unknown[] = [];
    const off: Unsubscribe = subscribe("member.joined", (payload) => {
      joined.push(payload);
    });

    try {
      const { user, org } = await register(signUp());
      expect(joined).toHaveLength(1);
      expect(joined[0]).toMatchObject({ orgId: org.id, userId: user.id, role: "owner" });
    } finally {
      off();
    }
  });

  it("is throttled on auth:register, before anything is written", async () => {
    const { capacity } = getBucketConfig("auth:register");
    for (let attempt = 0; attempt < capacity; attempt += 1) {
      await register(signUp());
    }

    const before = { users: countRows(users), orgs: countRows(organizations) };
    const refused = await register(signUp()).catch((e: unknown) => e);

    expect(refused).toBeInstanceOf(RateLimitedError);
    expect(toAppError(refused).code).toBe("rate_limited");
    expect({ users: countRows(users), orgs: countRows(organizations) }).toEqual(before);
  });

  it("charges a refused duplicate like any other attempt", async () => {
    const input = signUp();
    await register(input);

    const { capacity } = getBucketConfig("auth:register");
    for (let attempt = 1; attempt < capacity; attempt += 1) {
      await register(signUp({ email: input.email })).catch(() => undefined);
    }

    await expect(register(signUp())).rejects.toBeInstanceOf(RateLimitedError);
  });
});

describe("services/auth-service sign-in", () => {
  it("signs in with any spelling of the address used at sign-up", async () => {
    await register(signUp({ email: "Phone.Typed@Signup.test" }));

    for (const email of ["phone.typed@signup.test", "PHONE.TYPED@SIGNUP.TEST"]) {
      const { user } = await login({ email, password: PASSWORD, rememberMe: false });
      expect(user.email).toBe("phone.typed@signup.test");
    }
  });

  it("reports a throttled sign-in as rate_limited, not an internal error", async () => {
    const { capacity } = getBucketConfig("auth:login");
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ANONYMOUS_ORG, "auth:login");
    }

    const refused = await login({
      email: "nobody@signup.test",
      password: PASSWORD,
      rememberMe: false,
    }).catch((e: unknown) => e);

    expect(refused).toBeInstanceOf(RateLimitedError);
    expect(toAppError(refused)).toMatchObject({ code: "rate_limited" });
  });

  it("reports a throttled password-reset confirmation as rate_limited", async () => {
    const { capacity } = getBucketConfig("auth:password-reset");
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit(ANONYMOUS_ORG, "auth:password-reset");
    }

    const refused = await confirmPasswordReset({
      token: "t".repeat(32),
      password: PASSWORD,
      confirmPassword: PASSWORD,
    }).catch((e: unknown) => e);

    expect(refused).toBeInstanceOf(RateLimitedError);
    expect(toAppError(refused).code).toBe("rate_limited");
  });

  it("keeps a throttled password-reset request silent", async () => {
    const { capacity } = getBucketConfig("auth:password-reset");
    for (let i = 0; i < capacity; i += 1) {
      await consumeRateLimit("" as OrgId, "auth:password-reset");
      await consumeRateLimit(ANONYMOUS_ORG, "auth:password-reset");
    }

    const result = await requestPasswordResetAction({ email: "someone@signup.test" });
    expect(result.ok).toBe(true);
  });
});

